<template>
  <section class="maintenance" aria-label="典籍维护">
    <header><h3>典籍维护</h3><button type="button" :disabled="loading || busy" @click="refresh">刷新状态</button></header>
    <p v-if="loading" role="status">正在核对当前授权与维护状态…</p><p v-if="catalogError" class="error" role="status">{{ catalogError }}；既有维护单、撤任和取消控制不受目录状态影响。</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
    <p v-if="!hasAccess">当前身份没有典籍维护权限；请联系书库管理者授权。</p>
    <template v-else>
      <section v-if="can('appoint')"><h4>编修任职</h4><p>岗位：{{ capabilities?.appointmentStatus }}；目录：<code>{{ catalogSkill ? `${catalogSkill.key}@${catalogSkill.version}` : '当前目录不支持，不能任职' }}</code></p>
        <form v-if="!currentAppointment" @submit.prevent="appoint"><label>Agent ID <input v-model.trim="appointment.agentId" required /></label><label>绑定版本 <input v-model.trim="appointment.expectedBindingVersion" required /></label><label>岗位权限 <select v-model="appointment.permissionProfile"><option>DRAFT_ONLY</option><option>PUBLISH_VALIDATED</option></select></label><button :disabled="busy || !catalogSkill">明确任职</button></form>
        <p v-else>Agent {{ currentAppointment.agentId }} · {{ currentAppointment.permissionProfile }} · {{ currentAppointment.readiness }}</p><button v-if="currentAppointment" :disabled="busy" @click="revoke">撤任当前 Agent</button>
      </section>
      <section v-if="can('source.prepare')"><h4>固定来源快照</h4><p>仅接受管理者明确提供的 UTF-8 纯文本；上传不代表公开发布。</p><form @submit.prevent="prepareSource"><label>纯文本底本 <input ref="sourceFileInput" type="file" accept=".txt,text/plain" required @change="chooseSourceFile" /></label><label>底本名称 <input v-model.trim="sourceInput.sourceName" required /></label><label>固定版本说明 <input v-model.trim="sourceInput.sourceVersion" required /></label><label>公开用途权利依据 <input v-model.trim="sourceInput.rightsBasis" required /></label><button :disabled="busy">冻结来源快照</button></form><p v-if="preparedSource">已固定 {{ preparedSource.sourceId }} · {{ preparedSource.rawByteLength }} 字节 · SHA-256 {{ preparedSource.rawSha256 }}</p></section>
      <section v-if="can('job.create')"><h4>维护请求</h4><p>创建请求只确认业务意图，状态以服务端 job 为准。</p><form @submit.prevent="confirmRequest"><label>操作 <select v-model="request.operation"><option value="ADD_WORK">新增作品</option><option value="REVISE_WORK">修订作品</option></select></label><template v-if="request.operation === 'ADD_WORK'"><label>作品唯一 key <input v-model.trim="request.newWork.canonicalKey" required /></label><label>作品标题 <input v-model.trim="request.newWork.title" required /></label></template><label v-else>已有 workId <input v-model.trim="request.workId" required /></label><label>固定来源 ID <input v-model.trim="request.sourceId" required /></label><fieldset><legend>发布方式（明确选择）</legend><label><input v-model="request.requestedPublicationMode" type="radio" value="MANUAL" /> MANUAL：由管理者另行发布</label><label><input v-model="request.requestedPublicationMode" type="radio" value="AUTO" /> AUTO：仅由服务端按授权执行</label></fieldset><button :disabled="busy">确认维护请求</button></form><p v-if="confirmation">已获服务器确认：{{ confirmation.job?.state || '已受理' }}；{{ confirmation.readiness || '请读取作业状态' }}；下一步：{{ confirmation.nextAction || '读取作业' }}。</p><div v-if="confirmation?.confirmationRef"><button :disabled="busy" @click="openConversation('songjiang')">交宋江统筹</button><button :disabled="busy || !confirmation.job?.assignedAgentId" @click="openConversation('private')">直达受任 Agent</button></div></section>
      <section v-if="can('job.read') || can('job.manage') || can('job.create')"><h4>授权维护单</h4><label>选择维护单 <select v-model="selectedJobId" @change="openJob(selectedJobId)"><option value="">请选择</option><option v-for="item in jobs" :key="item.jobId" :value="item.jobId">{{ item.title || item.canonicalKey || item.jobId }} · {{ item.state }} · {{ item.waitReason || '无等待原因' }}</option></select></label>
        <template v-if="job"><p>作业 {{ job.jobId }} · {{ job.state }} · {{ job.waitReason || '当前无等待原因' }} · {{ job.publicationMode }}</p><p>Run {{ job.runId || '尚未创建' }}；发布 {{ job.publicationId || '未发布' }}。</p>
          <template v-if="can('draft.write')"><label>正文草稿 JSON<textarea v-model="draftJson" rows="12" spellcheck="false" /></label><p>草稿版本 {{ draft?.revision }}；状态 {{ draft?.state }}</p><button :disabled="busy || !draft" @click="saveDraft">按版本保存草稿</button><button v-if="can('validate')" :disabled="busy || !draft" @click="validateDraft">校验当前草稿</button><p v-if="validation">校验 {{ validation.outcome }} · 版本 {{ validation.draftRevision }}；{{ validation.findings?.join('；') }}</p><button v-if="can('publish')" :disabled="busy || validation?.outcome !== 'PASSED'" @click="publish">由管理者明确发布</button></template>
          <button v-if="can('job.manage')" :disabled="busy || !job.revision" @click="execute">创建或取得执行</button><form v-if="can('job.manage')" @submit.prevent="resume"><label>恢复原因 <input v-model.trim="recovery.reason" required /></label><button :disabled="busy">按原任职恢复</button></form><form v-if="can('job.manage')" @submit.prevent="reassign"><label>新任职 <select v-model="reassignment.newAppointmentId" required><option value="">请选择</option><option v-for="entry in recoveryContext?.candidates || []" :key="entry.appointmentId" :value="entry.appointmentId">{{ entry.agentId }} · {{ entry.appointmentId }}</option></select></label><button :disabled="busy">显式改派</button></form><button v-if="can('job.manage') && !['PUBLISHED','CANCELLED'].includes(job.state)" :disabled="busy" @click="cancelJob">明确取消维护单</button><ol class="events"><li v-for="event in events" :key="event.sequence">{{ event.sequence }} · {{ event.type || event.state || event.eventType }} · {{ event.message || event.waitReason || '' }}</li></ol></template>
      </section>
      <section v-if="unknownIntents.length"><h4>待核对的未知请求</h4><p>网络中断或服务端未明确响应时，原请求键、正文和版本会保留；不要以刷新或新请求替代核对。</p><ul><li v-for="item in unknownIntents" :key="item.intent"><code>{{ item.intent }}</code> · {{ item.method.toUpperCase() }} {{ item.path }}<button :disabled="busy" @click="reconcileIntent(item.intent)">按原键核对</button><button :disabled="busy" @click="acknowledgeIntent(item.intent)">明确确认旧请求可能已受理</button></li></ul></section><section v-if="can('job.create')"><h4>客户端技能准备</h4><form @submit.prevent="requestInstallation"><label>受任 Agent ID <input v-model.trim="installation.agentId" required /></label><label>当前绑定版本 <input v-model.trim="installation.bindingVersion" required /></label><button :disabled="busy || !catalogSkill">申请安装</button></form><p v-if="installationStatus">安装 {{ installationStatus.installationId || installationStatus.id }}：{{ installationStatus.status || installationStatus.state || installationStatus.waitReason || '等待服务器状态' }}</p><button v-if="installationStatus?.installationId || installationStatus?.id" :disabled="busy" @click="refreshInstallation">读取安装状态</button></section>
    </template>
  </section>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { registerIdentityCleanup } from '@/utils/identityLifecycle.js'
import { ARCHIVE_COLLECTION_ID, ARCHIVE_SKILL, createArchiveMaintenanceGateway, createIdentityFence } from '@/composables/juyiting/useArchiveMaintenance.js'
const props = defineProps({ gateway: { type: Object, default: null } })
const emit = defineEmits(['open-maintenance-entry'])
const gateway = props.gateway || createArchiveMaintenanceGateway()
const capabilities = ref(null), slot = ref(null), appointments = ref([]), jobs = ref([]), job = ref(null), events = ref([]), draft = ref(null), recoveryContext = ref(null), validation = ref(null), draftJson = ref(''), selectedJobId = ref(''), confirmation = ref(null), installationStatus = ref(null), catalog = ref([]), unknownIntents = ref([]), catalogError = ref(''), loading = ref(false), busy = ref(false), error = ref(''), message = ref('')
const appointment = ref({ agentId:'', expectedBindingVersion:'', permissionProfile:'DRAFT_ONLY' }), installation = ref({ agentId:'', bindingVersion:'' }), sourceInput = ref({ sourceName:'', sourceVersion:'', rightsBasis:'' }), sourceFileInput = ref(null), sourceFile = ref(null), preparedSource = ref(null), request = ref({ operation:'ADD_WORK', newWork:{ canonicalKey:'', title:'', language:'zh' }, workId:'', sourceId:'', requestedPublicationMode:'MANUAL' }), recovery = ref({ reason:'' }), reassignment = ref({ newAppointmentId:'' })
const identity = createIdentityFence(); let readSequence = 0; let authoritySignature = ''; let busyOwner = 0; let unregister = null
const can = action => capabilities.value?.allowedActions?.includes(action) ?? false
const hasAccess = computed(() => ['appoint','job.create','source.prepare','job.read','job.manage'].some(can))
const activeAppointments = computed(() => appointments.value.filter(x => x?.status === 'ACTIVE'))
const currentAppointment = computed(() => activeAppointments.value[0] || null)
const catalogSkill = computed(() => { const matches=catalog.value.filter(x=>x?.key===ARCHIVE_SKILL.key&&typeof x?.version==='string'&&typeof x?.packageSha256==='string'); return matches.length===1?matches[0]:null })
const current = epoch => identity.isCurrent(epoch)
const sameSelection = (epoch, sequence, id) => current(epoch) && readSequence === sequence && selectedJobId.value === id
const exactRevision = value => value == null ? null : String(value)
const clearDerived = () => { slot.value=null; appointments.value=[]; jobs.value=[]; job.value=null; events.value=[]; draft.value=null; recoveryContext.value=null; validation.value=null; draftJson.value=''; selectedJobId.value=''; confirmation.value=null; installationStatus.value=null; catalog.value=[]; unknownIntents.value=[]; catalogError.value=''; sourceFile.value=null; preparedSource.value=null; sourceInput.value={sourceName:'',sourceVersion:'',rightsBasis:''}; appointment.value={agentId:'',expectedBindingVersion:'',permissionProfile:'DRAFT_ONLY'}; installation.value={agentId:'',bindingVersion:''}; request.value={operation:'ADD_WORK',newWork:{canonicalKey:'',title:'',language:'zh'},workId:'',sourceId:'',requestedPublicationMode:'MANUAL'}; recovery.value={reason:''}; reassignment.value={newAppointmentId:''}; if(sourceFileInput.value) sourceFileInput.value.value='' }
const clear = () => { identity.invalidate(); readSequence++; authoritySignature=''; busyOwner++; gateway.clear?.(); capabilities.value=null; clearDerived(); error.value=''; message.value=''; loading.value=false; busy.value=false }
const isAuthFailure = value => value?.status===401 || value?.code==='AUTHENTICATION_REQUIRED'
const failClosed = () => { clear(); error.value='当前身份认证已失效；已清除典籍维护授权与表单数据。' }
const fail = x => x?.code === 'ARCHIVE_UNKNOWN_OPERATION' ? '此前请求结果未明确；请先读取并处理旧请求，不能改变正文或版本重发。' : x?.status === 409 ? '服务器发现并发编辑；请刷新后人工核对，不会自动覆盖。' : (x?.status == null || x?.status === 404 || x?.status >= 500) ? '请求结果尚不明确；已保留同一请求键与正文，请先读取权威状态。' : x?.data?.msg || x?.message || '操作失败。'
const syncRetained = () => { unknownIntents.value=Array.isArray(gateway.retainedIntents?.())?gateway.retainedIntents():[] }
const run = async (operation, success) => { if(busy.value) return; const epoch=identity.current(), owner=++busyOwner; busy.value=true; error.value=''; message.value=''; try { const result=await operation(epoch); if(current(epoch)) { syncRetained(); if(success)message.value=success } return result } catch(x) { if(current(epoch)) { syncRetained(); error.value=fail(x) } return null } finally { if(busyOwner===owner)busy.value=false } }
const reconcileIntent = intent => run(async epoch => { const result=await gateway.operationByKey(intent); if(!current(epoch))return; if(result?.state==='COMMITTED'){ const operation=result.operation||{}; gateway.acknowledgeRetainedIntent(intent); syncRetained(); const kind=operation.targetType||'资源'; const id=operation.targetId||''; message.value=`服务端已权威确认原请求：${kind}${id?` ${id}`:''}` } else if(result?.state==='UNSUPPORTED'){ error.value='此平台安装请求不能由典籍操作表推断结果；请读取安装状态。' } else error.value='服务端尚未确认该请求；原键和正文仍被保留。' }, null)
const acknowledgeIntent = intent => { gateway.acknowledgeRetainedIntent?.(intent); syncRetained(); message.value='已明确确认旧请求可能已受理；请先读取权威状态再继续。' }
const refresh = async () => { const epoch=identity.current(), sequence=++readSequence; loading.value=true; error.value=''; try { const caps=await gateway.capabilities(); if(!current(epoch)||sequence!==readSequence)return; const nextAuthority=Array.isArray(caps?.allowedActions)?[...caps.allowedActions].sort().join('|'):''; if(authoritySignature&&authoritySignature!==nextAuthority){ identity.invalidate(); readSequence++; busyOwner++; busy.value=false; gateway.clear?.(); clearDerived(); authoritySignature=nextAuthority; capabilities.value=caps; return await refresh() } authoritySignature=nextAuthority; capabilities.value=caps; syncRetained(); if(!caps?.allowedActions?.length){ clearDerived(); return } const wantsJobs=['job.read','job.manage','job.create'].some(can); const catalogRead=can('appoint')||can('job.create')?gateway.catalog().then(value=>({value:Array.isArray(value)?value:[],error:''})).catch(x=>{if(isAuthFailure(x))throw x;return {value:[],error:'当前技能目录不可用'}}):Promise.resolve({value:[],error:''}); const [catalogResult,nextSlot,nextAppointments,nextJobs]=await Promise.all([catalogRead,can('appoint')?gateway.slot():null,can('appoint')?gateway.appointments():[],wantsJobs?gateway.jobs():[]]); if(!current(epoch)||sequence!==readSequence)return; catalog.value=catalogResult.value; catalogError.value=catalogResult.error; slot.value=nextSlot; appointments.value=Array.isArray(nextAppointments)?nextAppointments:[]; jobs.value=Array.isArray(nextJobs)?nextJobs:[]; if(selectedJobId.value)await openJob(selectedJobId.value,epoch,sequence) } catch(x){if(current(epoch)&&sequence===readSequence){if(isAuthFailure(x))failClosed();else error.value=fail(x)}} finally {if(current(epoch)&&sequence===readSequence)loading.value=false} }
const openJob = async (id, epoch=identity.current(), sequence=++readSequence) => { job.value=null; draft.value=null; validation.value=null; draftJson.value=''; if(!id)return; try { const [nextJob,nextEvents,nextDraft,nextRecovery]=await Promise.all([gateway.job(id),gateway.events(id),can('draft.write')?gateway.draft(id):null,can('job.manage')?gateway.recoveryContext(id):null]); if(!sameSelection(epoch,sequence,id))return; job.value=nextJob; events.value=Array.isArray(nextEvents)?nextEvents:[]; recoveryContext.value=nextRecovery; draft.value=nextDraft; draftJson.value=JSON.stringify(nextDraft?.content || {blocks:[],excludedSourceRanges:[]},null,2) } catch(x){if(sameSelection(epoch,sequence,id))error.value=fail(x)} }
const appoint = () => run(async epoch => { const skill=catalogSkill.value; if(!skill)throw new Error('当前目录不支持此岗位技能'); await gateway.appoint({ ...appointment.value, workScopeMode:'COLLECTION', workIds:[], requiredSkill:{key:skill.key,version:skill.version,packageSha256:skill.packageSha256} },slot.value?.revision||'0'); if(current(epoch)) await refresh() },'任职已提交；仍须以服务端 readiness 与安装状态为准。')
const revoke = () => run(async epoch => { const value=currentAppointment.value; if(!value) return; await gateway.revoke(value.appointmentId,{reason:'manager action'},exactRevision(value.revision)); if(current(epoch))await refresh() },'任职已撤销。')
const chooseSourceFile = e => { sourceFile.value=e.target.files?.[0]||null; preparedSource.value=null; request.value.sourceId=''; if(sourceFile.value&&!sourceInput.value.sourceName)sourceInput.value.sourceName=sourceFile.value.name }
const base64 = bytes => { let s=''; for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192)); return btoa(s) }
const prepareSource = () => run(async epoch => { const file=sourceFile.value; if(!file||file.size<1||file.size>16*1024*1024)throw new Error('底本文件应为 1 字节至 16 MiB 的 UTF-8 文本'); if(!globalThis.crypto?.subtle)throw new Error('安全上下文的 SHA-256 能力不可用'); const bytes=new Uint8Array(await file.arrayBuffer()); if(!current(epoch)||file!==sourceFile.value)return; const digest=await crypto.subtle.digest('SHA-256',bytes); if(!current(epoch)||file!==sourceFile.value)return; const declaredSha256=Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join(''); const result=await gateway.prepareSource({...sourceInput.value,declaredSha256,contentBase64:base64(bytes)}); if(!current(epoch)||file!==sourceFile.value)return; preparedSource.value=result; request.value.sourceId=result.sourceId },'来源原始字节已固定；维护请求仍需另行确认。')
const confirmRequest = () => run(async epoch => { const value=request.value; const result=await gateway.confirm({collectionId:ARCHIVE_COLLECTION_ID,operation:value.operation,newWork:value.operation==='ADD_WORK'?{...value.newWork}:null,workId:value.operation==='REVISE_WORK'?value.workId:null,sourceId:value.sourceId,requestedPublicationMode:value.requestedPublicationMode}); if(!current(epoch))return; confirmation.value=result; if(result?.job?.jobId){selectedJobId.value=result.job.jobId; await refresh()} },'服务器已确认维护意图；请按权威 job 状态继续。')
const requestInstallation = () => run(async epoch => { const skill=catalogSkill.value; if(!skill)throw new Error('当前目录不支持此岗位技能'); const result=await gateway.install({agentId:installation.value.agentId,bindingVersion:installation.value.bindingVersion,skillKey:skill.key,skillVersion:skill.version}); if(current(epoch))installationStatus.value=result },'安装申请已受理；这不是安装成功、收费或发布。')
const refreshInstallation = () => run(async epoch => { const id=installationStatus.value?.installationId||installationStatus.value?.id; const result=await gateway.installation(id); if(current(epoch))installationStatus.value=result },'已读取服务器安装状态。')
const saveDraft = () => run(async epoch => { const body=JSON.parse(draftJson.value); if(!Array.isArray(body.blocks)||!Array.isArray(body.excludedSourceRanges))throw new Error('草稿须包含 blocks 和 excludedSourceRanges 数组'); const id=job.value?.jobId; await gateway.saveDraft(id,body,exactRevision(draft.value?.revision)); if(current(epoch)&&selectedJobId.value===id)await openJob(id) },'草稿已保存，之前的校验失效。')
const validateDraft = () => run(async epoch => { const id=job.value?.jobId; const value=await gateway.validate(id,exactRevision(draft.value?.revision)); if(!current(epoch)||selectedJobId.value!==id)return; validation.value=value },'已校验当前草稿版本。')
const publish = () => run(async epoch => { const id=job.value?.jobId; const state=job.value?.operation==='ADD_WORK'?{revision:'0',activeEditionId:null}:await gateway.workState(job.value.workId); if(!current(epoch)||selectedJobId.value!==id)return; await gateway.publish(id,{validationId:validation.value.validationId,expectedActiveEditionId:state.activeEditionId,expectedWorkRevision:state.revision},exactRevision(draft.value?.revision)); if(current(epoch))await refresh() },'发布事务已提交；请从书架核验读回。')
const cancelJob = () => { const reason=globalThis.prompt?.(`明确取消《${job.value?.title||''}》的维护单？请输入原因：`); if(!reason?.trim())return; return run(async epoch=>{const id=job.value.jobId;await gateway.cancel(id,{reason:reason.trim()},exactRevision(job.value.revision));if(current(epoch))await refresh()},'维护单已取消，旧执行权限被撤销。') }
const execute = () => run(async epoch=>{const id=job.value.jobId;await gateway.execute(id,exactRevision(job.value.revision));if(current(epoch))await openJob(id)},'已请求执行；请读取作业和事件确认实际状态。')
const resume = () => run(async epoch=>{const old=recoveryContext.value?.previousAppointment; if(!old)throw new Error('服务端恢复上下文不可用'); const id=job.value.jobId;await gateway.resume(id,{reason:recovery.value.reason,expectedAppointmentId:old.appointmentId,expectedAppointmentRevision:exactRevision(old.revision),expectedSkill:old.requiredSkill},exactRevision(recoveryContext.value.jobRevision));if(current(epoch))await openJob(id)},'已请求新 run/epoch；旧凭据不会被复用。')
const reassign = () => run(async epoch=>{const old=recoveryContext.value?.previousAppointment; const next=recoveryContext.value?.candidates?.find(x=>x?.appointmentId===reassignment.value.newAppointmentId);if(!old||!next)throw new Error('服务端恢复上下文不可用或未选择新任职');const id=job.value.jobId;await gateway.reassign(id,{reason:recovery.value.reason||'manager reassignment',expectedAppointmentId:old.appointmentId,expectedAppointmentRevision:exactRevision(old.revision),expectedSkill:old.requiredSkill,newAppointmentId:next.appointmentId,newAppointmentRevision:exactRevision(next.revision),newSkill:next.requiredSkill},exactRevision(recoveryContext.value.jobRevision));if(current(epoch))await openJob(id)},'已请求改派；服务端将建立新 run 并保留历史。')
const openConversation = entry => { const value=confirmation.value;if(value?.confirmationRef)emit('open-maintenance-entry',{entry,confirmationRef:value.confirmationRef,job:value.job}) }
onMounted(()=>{unregister=registerIdentityCleanup(clear);void refresh()});onBeforeUnmount(()=>{unregister?.();clear()})
</script>
<style scoped>.maintenance{min-height:0;overflow:auto;padding:12px;color:var(--work-ink,#242e2b);background:var(--work-paper,#fffefa)}.maintenance section{padding:12px 0;border-top:1px solid var(--work-line,#ddd)}.maintenance header{display:flex;justify-content:space-between;align-items:center;gap:8px}.maintenance form,.maintenance label{display:grid;gap:8px}.maintenance form{margin:12px 0}.maintenance fieldset{display:grid;gap:6px}.maintenance input,.maintenance select,.maintenance textarea{min-width:0;width:100%;box-sizing:border-box;padding:9px;border:1px solid #999;border-radius:6px;font:inherit}.maintenance textarea{font-family:monospace}.maintenance button{min-height:40px;margin:6px 8px 6px 0;padding:8px}.maintenance button:disabled{opacity:.5}.error{color:#9b2f26}.events{padding-left:22px}</style>
